// Band statistics from a sample of one row and column in step.
export async function bandStats(image, band, step = 20) {
  let n = 0;
  let sum = 0;
  let min = Infinity;
  let max = -Infinity;
  for (let y = 0; y < image.height; y += 1) {
    const row = await image.readRow(band, y);
    if (y % step !== 0) continue;
    for (let x = 0; x < row.length; x += step) {
      const v = row[x];
      if (!Number.isFinite(v)) continue;
      n += 1;
      sum += v;
      if (v < min) min = v;
      if (v > max) max = v;
    }
  }
  return { n, mean: sum / n, min, max };
}
